<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import {request,metric} from './console'
const data=ref<any>({}),connected=ref(false),error=ref('')
let timer:ReturnType<typeof setInterval>,pending=false,disposed=false
async function refresh(){if(pending)return;pending=true;try{const value=await request('service/status');if(!disposed){data.value=value;connected.value=true;error.value=''}}catch(e){if(!disposed){connected.value=false;error.value=e instanceof Error?e.message:'状态获取失败'}}finally{pending=false}}
onMounted(()=>{void refresh();timer=setInterval(refresh,2000)})
onUnmounted(()=>{disposed=true;clearInterval(timer)})
const time=(value:any)=>value?new Date(value).toLocaleString():'待获取'
</script>
<template><details class="service-health"><summary>服务 {{connected?data.service_status:'连接待确认'}} · Worker {{connected?(data.worker?.paused?'PAUSED':data.worker?.state??'待获取'):'状态待确认'}}</summary><div class="service-health-body"><p v-if="error" class="error">{{error}} <button @click="refresh">重新获取</button></p><dl><dt>Worker心跳</dt><dd>{{time(data.worker?.stability?.heartbeat_at)}}</dd><dt>最后成功动作</dt><dd>{{time(data.worker?.stability?.last_success_at)}}</dd><dt>当前识别目标</dt><dd>{{data.worker?.stability?.goal ? JSON.stringify(data.worker.stability.goal) : '待获取'}}</dd><dt>最近视觉结果</dt><dd>{{data.worker?.stability?.observation ? '阶段 '+data.worker.stability.observation.stage_id+' · 角色 '+data.worker.stability.observation.player+' · 校验分数 '+data.worker.stability.observation.confidence : '待获取'}}</dd><dt>重试 / 卡住秒数</dt><dd>{{metric(data.worker?.stability?.retry_count)}} / {{metric(data.worker?.stability?.stuck_seconds,1)}}</dd><dt>连续完成轮次</dt><dd>{{metric(data.worker?.completedSession)}} / {{metric(data.worker?.rounds)}}</dd><dt>进程运行秒数</dt><dd>{{metric(data.process_uptime_seconds,1)}}</dd><dt>内存（MiB） / CPU（单核%）</dt><dd>{{data.memory_bytes == null ? '待获取' : metric(data.memory_bytes/1048576,1)}} / {{metric(data.cpu_percent_one_core,1)}}</dd><dt>人工审核</dt><dd>{{data.worker?.stability?.manual_review_required ? '需要审核，禁止重启任务' : connected ? '未触发' : '待确认'}}</dd><dt>故障恢复记录</dt><dd><p v-for="(r,i) in data.worker?.stability?.recoveries ?? []" :key="i">{{time(r.at)}} · {{r.error}} · 重试{{r.retry}} · {{r.recovered_at ? '已恢复 '+time(r.recovered_at) : '未确认恢复'}}</p></dd><dt>服务进程</dt><dd>{{metric(data.pid)}}</dd><dt>服务启动</dt><dd>{{time(data.started_at)}}</dd><dt>最后心跳</dt><dd>{{time(data.heartbeat_at)}}</dd><dt>最近异常退出检测</dt><dd>{{data.last_unexpected_exit_detected_at?time(data.last_unexpected_exit_detected_at):connected?'未记录':'待获取'}}</dd><dt>Watchdog</dt><dd>{{connected?(data.watchdog_enabled?'已明确启用':'未启用'):'待获取'}} · {{data.watchdog_state??'待获取'}}</dd><dt>本次管理重启次数</dt><dd>{{metric(data.restart_count)}} / {{metric(data.max_restarts)}}</dd><dt>Agent恢复</dt><dd>{{data.recovery_status??'待获取'}}</dd><dt>恢复策略</dt><dd>{{data.recovery_policy??'待获取'}}</dd><dt>SSE连接 / 线程</dt><dd>{{metric(data.sse_clients)}} / {{metric(data.thread_count)}}</dd></dl><p>未知动作不重放，已完成奖励不重复结算。关闭页面不会停止后台Worker。</p></div></details></template>
<style scoped>.service-health{position:fixed;bottom:18px;right:22px;z-index:40;background:#152333;border:1px solid #365567;border-radius:8px;padding:10px;color:#d9e8ef;font-size:12px;max-width:420px}.service-health summary{cursor:pointer}.service-health-body{max-height:440px;overflow:auto}.service-health dl{display:grid;grid-template-columns:126px 1fr;gap:9px;padding:12px 0}.service-health dd{margin:0;overflow-wrap:anywhere}.service-health p{max-width:390px;line-height:1.6}</style>
